const INLINED_INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Guardrail Manager</title>\n<style>\n  :root { --bg:#0b0d10; --panel:#14181d; --panel2:#1a1f26; --line:#262c34;\n          --text:#e8e6e1; --dim:#9aa3ad; --accent:#7cc4ff; --red:#e2483a;\n          --green:#3fb97c; --amber:#e0a83c; }\n  * { box-sizing:border-box; }\n  body { margin:0; background:var(--bg); color:var(--text);\n         font-family:system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif; }\n  header { padding:14px 16px; border-bottom:1px solid var(--line);\n           display:flex; align-items:center; gap:10px; flex-wrap:wrap; }\n  header h1 { font-size:18px; margin:0; letter-spacing:.4px; }\n  header .sub { color:var(--dim); font-size:12px; width:100%; }\n  nav { display:flex; gap:8px; padding:10px 16px 0; }\n  nav button { flex:1; }\n  main { padding:14px 16px 40px; max-width:860px; margin:0 auto; }\n  button { background:var(--panel2); color:var(--text); border:1px solid var(--line);\n           border-radius:10px; padding:10px 14px; font-size:14px; cursor:pointer; }\n  button:active { transform:translateY(1px); }\n  button.primary { background:#12395a; border-color:#1d5a8a; }\n  button.danger { background:#4a1712; border-color:#7a2a20; }\n  button.on { outline:2px solid var(--accent); }\n  input, textarea { width:100%; background:var(--panel); color:var(--text);\n           border:1px solid var(--line); border-radius:10px; padding:10px;\n           font-size:14px; font-family:inherit; }\n  textarea { font-family:ui-monospace,Menlo,Consolas,monospace; min-height:180px; }\n  .card { background:var(--panel); border:1px solid var(--line); border-radius:12px;\n          padding:12px 14px; margin:10px 0; }\n  .repo { display:flex; align-items:center; gap:10px; cursor:pointer; }\n  .repo .name { font-weight:600; font-size:15px; }\n  .repo .desc { color:var(--dim); font-size:12px; }\n  .chip { font-size:11px; padding:3px 8px; border-radius:999px; border:1px solid var(--line);\n          white-space:nowrap; }\n  .chip.config { color:var(--green); border-color:var(--green); }\n  .chip.floor { color:var(--amber); border-color:var(--amber); }\n  .chip.none, .chip.unscanned { color:var(--dim); }\n  .file { border-top:1px solid var(--line); padding:10px 0; }\n  .file:first-child { border-top:none; }\n  .file .path { font-family:ui-monospace,Menlo,monospace; font-size:13px; word-break:break-all; }\n  .file .label { color:var(--dim); font-size:12px; margin:3px 0 8px; }\n  .lock { color:var(--amber); font-size:12px; }\n  .row { display:flex; gap:8px; flex-wrap:wrap; margin:10px 0; }\n  .row button { flex:1; min-width:120px; }\n  .entry { display:flex; gap:8px; align-items:center; padding:6px 0;\n           border-bottom:1px solid var(--line); }\n  .entry span { flex:1; font-family:ui-monospace,Menlo,monospace; font-size:13px;\n                word-break:break-all; }\n  pre.view { background:#0e1114; border:1px solid var(--line); border-radius:10px;\n             padding:10px; overflow:auto; max-height:50vh; font-size:12px;\n             white-space:pre-wrap; word-break:break-word; }\n  .msg { padding:10px 12px; border-radius:10px; margin:10px 0; font-size:13px; display:none; }\n  .msg.ok { background:#123324; display:block; }\n  .msg.err { background:#4a1712; display:block; }\n  .note { color:var(--dim); font-size:13px; line-height:1.5; }\n  h2 { font-size:16px; margin:18px 0 6px; }\n  .hidden { display:none; }\n  #login { max-width:420px; margin:60px auto; padding:0 16px; }\n</style>\n</head>\n<body>\n\n<div id=\"login\" class=\"hidden\">\n  <h1>Guardrail Manager</h1>\n  <p class=\"note\">Enter the access code to open the console.</p>\n  <input id=\"code\" type=\"password\" placeholder=\"Access code\" autocomplete=\"off\">\n  <div class=\"row\"><button class=\"primary\" onclick=\"login()\">Open</button></div>\n  <div id=\"loginmsg\" class=\"msg\"></div>\n</div>\n\n<div id=\"app\" class=\"hidden\">\n  <header>\n    <h1>Guardrail Manager</h1>\n    <div class=\"sub\">Deployment policy templates are yours to edit. The hard floor is code, shown read-only.</div>\n  </header>\n  <nav>\n    <button id=\"nav-repos\" class=\"on\" onclick=\"showView('repos')\">Repos</button>\n    <button id=\"nav-default\" onclick=\"showView('default')\">Template Default</button>\n  </nav>\n  <main>\n    <div id=\"msg\" class=\"msg\"></div>\n\n    <section id=\"view-repos\">\n      <div class=\"row\">\n        <button onclick=\"loadRepos(true)\">Rescan all repos</button>\n      </div>\n      <div id=\"repo-list\"></div>\n    </section>\n\n    <section id=\"view-repo\" class=\"hidden\">\n      <div class=\"row\"><button onclick=\"showView('repos')\">&larr; All repos</button></div>\n      <h2 id=\"repo-title\"></h2>\n      <div id=\"repo-files\"></div>\n    </section>\n\n    <section id=\"view-file\" class=\"hidden\">\n      <div class=\"row\"><button onclick=\"backToRepo()\">&larr; Back to repo</button></div>\n      <h2 id=\"file-title\" style=\"font-family:ui-monospace,Menlo,monospace;font-size:14px;word-break:break-all\"></h2>\n      <p id=\"file-label\" class=\"note\"></p>\n      <div id=\"file-body\"></div>\n    </section>\n\n    <section id=\"view-default\" class=\"hidden\">\n      <h2>Template default policy</h2>\n      <p class=\"note\">This is the template default that ships with the apps. When a\n      customer deploys one of the platforms, this file is the starting policy file\n      bundled with the template. They can edit it per deployment later, and so can\n      you, per repo, from the repo list. It controls only the soft policy layer:\n      an empty entry list means no soft blocks. The hard floor is separate code\n      and is not part of this file.</p>\n      <textarea id=\"default-text\"></textarea>\n      <div class=\"row\">\n        <button class=\"primary\" onclick=\"saveDefault()\">Save template default</button>\n      </div>\n    </section>\n  </main>\n</div>\n\n<script>\nlet currentRepo = null, currentFile = null, reposCache = [];\n\nfunction say(text, ok) {\n  const m = document.getElementById('msg');\n  m.textContent = text; m.className = 'msg ' + (ok ? 'ok' : 'err');\n  window.scrollTo(0, 0);\n}\nasync function api(path, opts) {\n  const res = await fetch(path, opts);\n  const data = await res.json().catch(() => ({}));\n  if (res.status === 401) { showLogin(); throw new Error('sign in required'); }\n  if (!res.ok) throw new Error(data.error || ('HTTP ' + res.status));\n  return data;\n}\nfunction post(path, body) {\n  return api(path, { method:'POST', headers:{'Content-Type':'application/json'},\n                     body: JSON.stringify(body || {}) });\n}\nfunction esc(s) { return String(s ?? '').replace(/[&<>\"']/g,\n  c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])); }\n\nfunction showLogin() {\n  document.getElementById('login').classList.remove('hidden');\n  document.getElementById('app').classList.add('hidden');\n}\nasync function login() {\n  const code = document.getElementById('code').value;\n  const res = await fetch('/api/login', { method:'POST',\n    headers:{'Content-Type':'application/json'}, body: JSON.stringify({code}) });\n  if (!res.ok) {\n    const m = document.getElementById('loginmsg');\n    m.textContent = 'Wrong access code.'; m.className = 'msg err'; return;\n  }\n  document.getElementById('login').classList.add('hidden');\n  document.getElementById('app').classList.remove('hidden');\n  loadRepos(false); loadDefault();\n}\nfunction showView(v) {\n  for (const id of ['repos','repo','file','default'])\n    document.getElementById('view-' + id).classList.toggle('hidden',\n      v !== id && !(v === 'repos' && id === 'repos'));\n  document.getElementById('nav-repos').classList.toggle('on', v !== 'default');\n  document.getElementById('nav-default').classList.toggle('on', v === 'default');\n}\n\nfunction chip(status) {\n  if (status === 'config') return '<span class=\"chip config\">has policy template</span>';\n  if (status === 'floor-only') return '<span class=\"chip floor\">hard floor only</span>';\n  if (status === 'guard-code') return '<span class=\"chip none\">guard code / detector only</span>';\n  if (status === 'none') return '<span class=\"chip none\">none found</span>';\n  return '<span class=\"chip unscanned\">not scanned</span>';\n}\nasync function loadRepos(rescan) {\n  const list = document.getElementById('repo-list');\n  list.innerHTML = '<p class=\"note\">Loading repos' + (rescan ? ' and scanning (first scan can take a bit)' : '') + '...</p>';\n  try {\n    const data = await api('/api/repos' + (rescan ? '?rescan=1' : ''));\n    reposCache = data.repos;\n    list.innerHTML = reposCache.map(r =>\n      '<div class=\"card repo\" onclick=\"openRepo(\\'' + esc(r.name) + '\\')\">' +\n      '<div style=\"flex:1\"><div class=\"name\">' + esc(r.name) + '</div>' +\n      '<div class=\"desc\">' + esc(r.description) + '</div></div>' + chip(r.status) + '</div>'\n    ).join('') || '<p class=\"note\">No repos found.</p>';\n  } catch (e) { say(e.message, false); }\n}\n\nasync function openRepo(name) {\n  currentRepo = name;\n  document.getElementById('repo-title').textContent = name;\n  const box = document.getElementById('repo-files');\n  box.innerHTML = '<p class=\"note\">Scanning...</p>';\n  showView('repo');\n  try {\n    const scan = await api('/api/repos/' + encodeURIComponent(name));\n    renderRepoFiles(scan);\n    const cached = reposCache.find(r => r.name === name);\n    if (cached) { cached.status = scan.status; cached.files = scan.files; }\n  } catch (e) { say(e.message, false); }\n}\nfunction renderRepoFiles(scan) {\n  const box = document.getElementById('repo-files');\n  const files = scan.files || [];\n  const configs = files.filter(f => f.kind === 'config');\n  const floor = files.filter(f => f.kind !== 'config');\n  let html = '';\n  html += '<h2>Deployment policy template</h2>';\n  if (configs.length) {\n    html += configs.map(f =>\n      '<div class=\"file\"><div class=\"path\">' + esc(f.path) + '</div>' +\n      '<div class=\"label\">' + esc(f.label) + '</div>' +\n      '<div class=\"row\"><button class=\"primary\" onclick=\"openFile(\\'' + esc(f.path) + '\\')\">Edit policy</button></div></div>'\n    ).join('');\n  } else {\n    html += '<p class=\"note\">No policy template file in this repo yet. The template default can be added as one.</p>' +\n      '<div class=\"row\"><button class=\"primary\" onclick=\"createConfig()\">Add template default as policy file</button></div>';\n  }\n  html += '<h2>Hard floor and other guard code</h2>';\n  if (floor.length) {\n    html += '<p class=\"note\">Hard floor, not editable here. These are hardcoded checks in code (stolen cards, phishing/fraud, wallet theft, unauthorized hacking, weapons of mass harm, CSAM, doxxing, and the money/approval/scope gates). View only.</p>';\n    html += floor.map(f =>\n      '<div class=\"file\"><div class=\"path\">' + esc(f.path) + '</div>' +\n      '<div class=\"label\">' + esc(f.label) + ' &middot; <span class=\"lock\">view only</span></div>' +\n      '<div class=\"row\"><button onclick=\"openFile(\\'' + esc(f.path) + '\\')\">View</button></div></div>'\n    ).join('');\n  } else {\n    html += '<p class=\"note\">No hard-floor or guard code files found in this repo.</p>';\n  }\n  if (scan.error) html += '<p class=\"note\">Scan note: ' + esc(scan.error) + '</p>';\n  box.innerHTML = html;\n}\nfunction backToRepo() { if (currentRepo) openRepo(currentRepo); else showView('repos'); }\n\nasync function openFile(path) {\n  try {\n    const f = await api('/api/repos/' + encodeURIComponent(currentRepo) +\n                        '/file?path=' + encodeURIComponent(path));\n    currentFile = f;\n    document.getElementById('file-title').textContent = f.path;\n    document.getElementById('file-label').textContent = f.label +\n      (f.editable ? '' : ' - hard floor, not editable here.');\n    const body = document.getElementById('file-body');\n    if (!f.editable) {\n      body.innerHTML = '<pre class=\"view\">' + esc(f.content) + '</pre>';\n    } else {\n      body.innerHTML = editorHtml(f);\n      wireEditor(f);\n    }\n    showView('file');\n  } catch (e) { say(e.message, false); }\n}\nfunction editorHtml(f) {\n  const entries = (f.entries || []).map(e =>\n    '<div class=\"entry\"><span>' + esc(e) + '</span>' +\n    '<button class=\"danger\" data-remove=\"' + esc(e) + '\">Remove</button></div>').join('');\n  if (f.embedded) {\n    return '<h2>Policy entries (refusal patterns for this deployment)</h2>' +\n      '<div id=\"entries\">' + (entries || '<p class=\"note\">No entries. Zero entries means no soft blocks.</p>') + '</div>' +\n      '<div class=\"row\"><input id=\"new-entry\" placeholder=\"New policy entry\">' +\n      '<button id=\"btn-add\">Add entry &amp; push</button></div>' +\n      '<div class=\"row\"><button id=\"btn-apply\">Apply template default</button>' +\n      '<button class=\"danger\" id=\"btn-clear\">Clear all entries &amp; push</button></div>' +\n      '<p class=\"note\">This template lives in a code module the app imports, so the entry lists are editable here but the module itself is not raw-editable or deletable from this app (deleting it would break the app build). Clearing the lists to zero means no soft blocks. The hard floor is in separate files and is not affected.</p>' +\n      '<h2>File (view only)</h2><pre class=\"view\">' + esc(f.content) + '</pre>';\n  }\n  return '<h2>Entries</h2>' +\n    '<div id=\"entries\">' + (entries || '<p class=\"note\">No entries. Zero entries means no soft blocks.</p>') + '</div>' +\n    '<div class=\"row\"><input id=\"new-entry\" placeholder=\"New policy entry\">' +\n    '<button onclick=\"addEntry()\">Add entry</button></div>' +\n    '<h2>Raw file</h2>' +\n    '<textarea id=\"raw\">' + esc(f.content) + '</textarea>' +\n    '<div class=\"row\">' +\n      '<button class=\"primary\" id=\"btn-save\">Save &amp; push</button>' +\n      '<button id=\"btn-apply\">Apply template default</button>' +\n    '</div><div class=\"row\">' +\n      '<button class=\"danger\" id=\"btn-clear\">Clear all entries</button>' +\n      '<button class=\"danger\" id=\"btn-delete\">Delete policy file</button>' +\n    '</div>' +\n    '<p class=\"note\">Deleting or emptying this file is safe by design: no policy file (or an empty one) means no soft blocks. The hard floor lives in separate code and is not affected.</p>';\n}\nfunction entriesNow() {\n  const raw = document.getElementById('raw').value.trim();\n  try {\n    const data = JSON.parse(raw);\n    if (Array.isArray(data)) return data.map(String);\n    if (data && typeof data === 'object') {\n      for (const k of ['entries','blocklist','block_list','rules','patterns','blocked','deny','denylist','deny_list','phrases'])\n        if (Array.isArray(data[k])) return data[k].map(String);\n      return [];\n    }\n  } catch (e) {}\n  return raw.split('\\n').map(s => s.trim()).filter(s => s && !s.startsWith('#') && !s.startsWith('//'));\n}\nfunction setEntries(entries) {\n  const rawEl = document.getElementById('raw');\n  let data = null;\n  try { data = JSON.parse(rawEl.value.trim()); } catch (e) {}\n  if (Array.isArray(data)) { rawEl.value = JSON.stringify(entries, null, 2) + '\\n'; }\n  else if (data && typeof data === 'object') {\n    let done = false;\n    for (const k of ['entries','blocklist','block_list','rules','patterns','blocked','deny','denylist','deny_list','phrases'])\n      if (Array.isArray(data[k])) { data[k] = entries; done = true; break; }\n    if (!done) data.entries = entries;\n    rawEl.value = JSON.stringify(data, null, 2) + '\\n';\n  } else { rawEl.value = entries.join('\\n') + (entries.length ? '\\n' : ''); }\n  currentFile.content = rawEl.value; currentFile.entries = entries;\n  document.getElementById('file-body').innerHTML = editorHtml(currentFile);\n  wireEditor(currentFile);\n}\nfunction entryOp(action, entry) {\n  return post('/api/repos/' + encodeURIComponent(currentRepo) + '/' + action,\n    { path: currentFile.path, entry: entry || '' });\n}\nfunction wireEditor(f) {\n  if (f.embedded) {\n    document.querySelectorAll('[data-remove]').forEach(btn =>\n      btn.onclick = async () => {\n        try {\n          const r = await entryOp('remove-entry', btn.dataset.remove);\n          say('Entry removed and pushed. Commit ' + String(r.commit).slice(0, 8), true);\n          openFile(currentFile.path);\n        } catch (e) { say(e.message, false); }\n      });\n    document.getElementById('btn-add').onclick = async () => {\n      const val = document.getElementById('new-entry').value.trim();\n      if (!val) return;\n      try {\n        const r = await entryOp('add-entry', val);\n        say('Entry added and pushed. Commit ' + String(r.commit).slice(0, 8), true);\n        openFile(currentFile.path);\n      } catch (e) { say(e.message, false); }\n    };\n    document.getElementById('btn-apply').onclick = async () => {\n      if (!confirm('Replace this repo policy entries with the template default entries?')) return;\n      try {\n        const r = await post('/api/repos/' + encodeURIComponent(currentRepo) + '/apply-default', {});\n        say('Template default applied and pushed. Commit ' + String(r.commit).slice(0, 8), true);\n        openFile(currentFile.path);\n      } catch (e) { say(e.message, false); }\n    };\n    document.getElementById('btn-clear').onclick = async () => {\n      if (!confirm('Clear all entries and push? Zero entries means no soft blocks.')) return;\n      try {\n        const r = await entryOp('clear-entries');\n        say('All entries cleared and pushed. Commit ' + String(r.commit).slice(0, 8), true);\n        openFile(currentFile.path);\n      } catch (e) { say(e.message, false); }\n    };\n    return;\n  }\n  document.querySelectorAll('[data-remove]').forEach(btn =>\n    btn.onclick = () => setEntries(entriesNow().filter(e => e !== btn.dataset.remove)));\n  document.getElementById('btn-save').onclick = async () => {\n    try {\n      const r = await post('/api/repos/' + encodeURIComponent(currentRepo) + '/save',\n        { path: currentFile.path, content: document.getElementById('raw').value });\n      say('Saved and pushed. Commit ' + String(r.commit).slice(0, 8), true);\n    } catch (e) { say(e.message, false); }\n  };\n  document.getElementById('btn-apply').onclick = async () => {\n    if (!confirm('Replace this repo policy with the template default?')) return;\n    try {\n      const r = await post('/api/repos/' + encodeURIComponent(currentRepo) + '/apply-default', {});\n      say('Template default applied and pushed. Commit ' + String(r.commit).slice(0, 8), true);\n      openFile(currentFile.path);\n    } catch (e) { say(e.message, false); }\n  };\n  document.getElementById('btn-clear').onclick = () => {\n    if (!confirm('Clear all entries? The file stays, with zero entries (no soft blocks). Then Save & push.')) return;\n    setEntries([]);\n  };\n  document.getElementById('btn-delete').onclick = async () => {\n    if (!confirm('Delete this policy file from the repo and push? No policy file means no soft blocks. This only deletes the policy template file, never hard-floor code.')) return;\n    try {\n      const r = await post('/api/repos/' + encodeURIComponent(currentRepo) + '/delete',\n        { path: currentFile.path });\n      say('Policy file deleted and pushed. Commit ' + String(r.commit).slice(0, 8), true);\n      backToRepo();\n    } catch (e) { say(e.message, false); }\n  };\n}\nfunction addEntry() {\n  const input = document.getElementById('new-entry');\n  const val = input.value.trim();\n  if (!val) return;\n  const entries = entriesNow();\n  if (!entries.includes(val)) entries.push(val);\n  setEntries(entries);\n}\nasync function createConfig() {\n  try {\n    const r = await post('/api/repos/' + encodeURIComponent(currentRepo) + '/create-config', {});\n    say('Policy file created from the template default and pushed. Commit ' + String(r.commit).slice(0, 8), true);\n    openRepo(currentRepo);\n  } catch (e) { say(e.message, false); }\n}\nasync function loadDefault() {\n  try {\n    const d = await api('/api/default');\n    document.getElementById('default-text').value = d.text;\n  } catch (e) {}\n}\nasync function saveDefault() {\n  try {\n    await post('/api/default', { text: document.getElementById('default-text').value });\n    say('Template default saved. It is the starting policy file bundled with the templates.', true);\n  } catch (e) { say(e.message, false); }\n}\n\n// Try an authed call; if the session is gone, show login.\napi('/api/repos').then(d => {\n  document.getElementById('login').classList.add('hidden');\n  document.getElementById('app').classList.remove('hidden');\n  reposCache = d.repos; loadRepos(false); loadDefault();\n}).catch(() => showLogin());\n</script>\n</body>\n</html>\n";
